import{_ as n,l as r,o as a,c as i,v as t,p as c,x as s,d as l,i as d,S as h}from"./chunks/framework.InCnrqk-.js";const P=JSON.parse('{"title":"多路 socket 互连","description":"","frontmatter":{"title":"多路 socket 互连","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/multi-socket-interconnect.md","filePath":"cs/multi-socket-interconnect.md","lastUpdated":1789023840000}'),m={name:"cs/multi-socket-interconnect.md"};function p(f,e,A,_,k,u){const o=r("Mermaid");return a(),i("div",null,[e[1]||(e[1]=t('<h1 id="多路-socket-互连" tabindex="-1">多路 socket 互连 <a class="header-anchor" href="#多路-socket-互连" aria-label="Permalink to &quot;多路 socket 互连&quot;">​</a></h1><div class="epigraph"><p>两颗 CPU 各有自己的 LLC 与内存；目录要跨插座转发，延迟从片上几跳变成板级几十纳秒，NUMA 成为程序员可见的布局问题。</p><footer>—— 据 Hennessy and Patterson, CA:AQA；Intel QPI/UPI 与 AMD Infinity Fabric 的公开描述 整理</footer></div><p><a href="/cs/noc-routing-deadlock">上一课</a> 保证片上包不会死锁。服务器把多颗封装连在一起，每颗下面挂本地 DRAM。<a href="/cs/directory-scalability">目录</a> 的 home 可能在另一颗芯片。本课不重讲 XY 路由。缺口是 <strong>socket 互连：一致性域跨芯片，带宽与延迟不对称。</strong></p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>单 socket mesh 的 LLC 命中是几到十几 ns。跨 socket 读要经过互连控制器、物理层、对端目录，再可能到对端 DRAM。缺口不是再选一个 fat-tree 当片上图，而是<strong>把远程 cache/内存当成另一层层次，并承认带宽远低于本地内存。</strong></p><p><span class="marginnote">UPI / Infinity Fabric：点对点链路，跑一致性与 I/O。链路条数决定对分。编程上就是 NUMA：线程与内存绑错则每记 miss 都付远程税。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>每 socket 一个或多个代理：把片上一致性事务翻译成片间包，维持 <a href="/cs/moesi-mesif">MOESI/MESIF</a> 的全局不变式。远程命中：对端 LLC 或内存。广播在片间更贵，故更依赖目录。I/O 与加速器可挂在某一 socket，变成又一层不对称。</p>',8)),(a(),c(h,null,{default:s(()=>[d(o,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20S0%5B%22socket%200%20%E7%9B%AE%E5%BD%95%22%5D%20--%3E%20LNK%5B%22%E7%89%87%E9%97%B4%E9%93%BE%E8%B7%AF%22%5D%0A%20%20S1%5B%22socket%201%20%E7%9B%AE%E5%BD%95%22%5D%20--%3E%20LNK%0A%20%20LNK%20--%3E%20DRAM0%5B%22%E6%9C%AC%E5%9C%B0%20DRAM%22%5D%0A%20%20LNK%20--%3E%20DRAM1%5B%22%E8%BF%9C%E7%A8%8B%20DRAM%22%5D%0A"})]),fallback:s(()=>[...e[0]||(e[0]=[l(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p><a href="/cs/mlp-memory-parallelism">MLP</a> 仍能重叠远程 miss，但每条更长，需要更多 MSHR。<a href="/cs/fence-cost">fence</a> 与锁的临界区跨 socket 时放大。OS <a href="/cs/numa-sched">NUMA 调度</a> 是软件对策；本课只要求硬件提供不对称延迟。Gustafson 与扩展下一课开始从性能模型收口，不再加协议态。</p><p>目录 home 若总在远端，即使数据后来缓存在本地 L3，第一次仍要跨链路。地址交织与 homing 策略决定「哪些行永远远程」。编程上 first-touch 分配是在利用这一几何。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把 CXL 设备树写完。也不把多机 Infiniband 当同一课——那是机柜网络，一致性域通常不跨。并行加速比定律下一课。</p><p>后课默认：跨 socket 是 NUMA 一致性域。加速比该用哪条定律，先分清问题规模是否随机器涨。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>多 socket 把目录与内存变远程，NUMA 延迟进入每次 miss。</li><li>片间链路条数限制对分带宽。</li><li>加速比：Gustafson 与 Amdahl 的规模假设不同，下一课。</li><li>出处：Hennessy and Patterson, <em>CA:AQA</em>；QPI/UPI、Infinity Fabric 公开文档。</li></ul>',8))])}const I=n(m,[["render",p]]);export{P as __pageData,I as default};
